                or any(ch not in "0123456789abcdef" for ch in hex_text)
                or len(hex_text) // 2 > MAX_COST):
            fail(5)
        payload = bytes.fromhex(hex_text)
        result = compute_fragment(ident, ttl, mtus, payload)
